package ro.leo.visual;
import android.content.Context;import android.graphics.*;import android.media.audiofx.Visualizer;import android.view.View;
/** Real FFT display for the current player session; never captures microphone input. */
final class MusicFace extends View {
    private final RetroStyle art=new RetroStyle();private Appearance.Palette palette;private Visualizer visualizer;private int session=-1;private volatile float[] spectrum=new float[12];private String meter="Spectru · în așteptare";private boolean failed;private volatile boolean captured;
    MusicFace(Context c){super(c);palette=Appearance.palette(c);setFocusable(true);requestFocus();}
    void appearance(){palette=Appearance.palette(getContext());invalidate();}
    void release(){if(visualizer!=null){try{visualizer.setEnabled(false);visualizer.release();}catch(RuntimeException ignored){}visualizer=null;}session=-1;captured=false;spectrum=new float[12];}
    void tick(){PlaybackService service=PlaybackService.instance;int wanted=service==null?0:service.audioSession();boolean playing=service!=null&&service.playing();
        if(wanted!=session){release();session=wanted;failed=false;if(wanted>0)try{visualizer=new Visualizer(wanted);if(visualizer.setCaptureSize(256)!=Visualizer.SUCCESS)throw new IllegalStateException();if(visualizer.setDataCaptureListener(new Visualizer.OnDataCaptureListener(){public void onWaveFormDataCapture(Visualizer v,byte[] data,int rate){}public void onFftDataCapture(Visualizer v,byte[] fft,int rate){float[] values=new float[12];for(int i=0;i<values.length;i++){int lo=1+(i*i*126)/(12*12),hi=Math.max(lo+1,1+((i+1)*(i+1)*126)/(12*12));float energy=0;for(int bin=lo;bin<hi&&bin*2+1<fft.length;bin++)energy=Math.max(energy,(float)Math.hypot(fft[bin*2],fft[bin*2+1]));values[i]=(float)Math.min(1,Math.log1p(energy)/Math.log(128));}spectrum=values;captured=true;}},Math.min(8000,Visualizer.getMaxCaptureRate()),false,true)!=Visualizer.SUCCESS)throw new IllegalStateException();if(visualizer.setEnabled(playing)!=Visualizer.SUCCESS)throw new IllegalStateException();}catch(RuntimeException e){release();session=wanted;failed=true;}}
        if(visualizer!=null)try{if(visualizer.getEnabled()!=playing&&visualizer.setEnabled(playing)!=Visualizer.SUCCESS)throw new IllegalStateException();}catch(RuntimeException e){release();session=wanted;failed=true;}
        meter=failed?"Spectru indisponibil":playing?(captured?"SPECTRU AUDIO · LIVE":"Spectru · conectare…"):"Spectru · pauză";if(!playing)spectrum=new float[12];invalidate();
    }
    private void panel(Canvas c,float l,float t,float r,float b,int color){Paint p=art.p;p.setShader(null);p.setStyle(Paint.Style.FILL);p.setColor(color);c.drawRoundRect(l,t,r,b,6,6,p);}
    private void label(Canvas c,String value,float x,float y,int size,int color,float width){Paint p=art.p;p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));p.setTextSize(size);if(value==null)value="";if(p.measureText(value)>width){int count=p.breakText(value,true,Math.max(0,width-p.measureText("…")),null);value=value.substring(0,count)+"…";}art.text(c,value,x,y,size,color,Paint.Align.LEFT);}
    static String[] titleLines(String title,Paint p,float width){title=title==null?"":title.replace('\n',' ');int cut=p.breakText(title,true,width,null);if(cut<title.length()){int space=title.lastIndexOf(' ',cut);if(space>0)cut=space;}return new String[]{title.substring(0,cut),title.substring(cut).trim()};}
    protected void onDraw(Canvas c){super.onDraw(c);c.save();c.scale(getWidth()/240f,getHeight()/302f);c.drawColor(palette.background);Paint p=art.p;
        panel(c,0,0,240,37,palette.bar);label(c,"Muzică Leo",12,26,21,Color.WHITE,216);p.setColor(palette.accent);c.drawRect(12,37,228,39,p);
        PlaybackService service=PlaybackService.instance;int position=service==null?0:service.position(),duration=service==null?0:service.duration();boolean playing=service!=null&&service.playing();
        panel(c,12,49,228,149,palette.card);Bitmap cover=service==null?null:service.cover();
        if(cover!=null&&!cover.isRecycled()){p.setColor(Color.WHITE);c.save();Path clip=new Path();clip.addRoundRect(new RectF(20,59,96,135),5,5,Path.Direction.CW);c.clipPath(clip);c.drawBitmap(cover,null,new RectF(20,59,96,135),p);c.restore();}
        else{panel(c,20,59,96,135,Appearance.mix(palette.accent,palette.background,.76f));p.setColor(palette.accent);c.drawCircle(58,97,28,p);p.setColor(palette.background);c.drawCircle(58,97,19,p);p.setColor(palette.accent);c.drawCircle(58,97,5,p);}
        p.setTextSize(16);p.setTypeface(Typeface.create("sans-serif",Typeface.NORMAL));String title=PlaybackService.title.isEmpty()?"Alege o piesă":PlaybackService.title;String[] lines=titleLines(title,p,110);label(c,lines[0],108,77,16,Color.WHITE,110);label(c,lines[1],108,98,16,Color.WHITE,110);
        label(c,service==null||service.queue.titles.isEmpty()?"Bibliotecă Leo":"Piesa "+(service.queue.index+1)+" / "+service.queue.titles.size(),108,119,12,palette.accent,110);label(c,PlaybackService.state,108,138,11,0xffc4cada,110);
        panel(c,12,157,228,200,palette.card);label(c,meter,20,171,10,palette.accent,200);float[] bands=spectrum;for(int i=0;i<12;i++){float x=21+i*17;for(int j=0;j<4;j++){p.setColor(bands[i]>(j+1)/5f?Appearance.mix(palette.accent,Color.WHITE,j*.09f):0x254f7980);c.drawRoundRect(x,193-j*5,x+11,196-j*5,1,1,p);}}
        panel(c,14,211,226,216,0x445f6b7d);float fraction=duration>0?Math.max(0,Math.min(1,position/(float)duration)):0;if(fraction>0)panel(c,14,211,14+212*fraction,216,palette.accent);label(c,MediaActivity.format(position)+" / "+MediaActivity.format(duration),14,232,12,Color.WHITE,110);label(c,"← → caută · ↑ ↓ volum",116,232,10,0xffc4cada,112);
        for(int i=0;i<3;i++){panel(c,12+i*74,243,80+i*74,272,i==1?palette.selection:palette.card);label(c,i==0?"4  ◀◀":i==2?"6  ▶▶":playing?"5  Pauză":"5  Redă",19+i*74,262,12,i==1?palette.ink:Color.WHITE,56);}
        panel(c,0,280,240,302,palette.bar);label(c,"Opțiuni",7,296,11,Color.WHITE,64);label(c,playing?"Pauză":"Redă",103,296,12,palette.accent,50);label(c,"Bibliotecă",187,296,11,Color.WHITE,48);c.restore();
    }
}
